payload.text:
In order to implement the monthly synchronization logic using the existing database structure, I will update `types.ts` to support a payment history structure and refactor `App.tsx` to handle this logic using the `payment_date` field as a JSON storage for multiple months.

# Updated files:

## types.ts

Added `paymentHistory` to the `Player` interface to support multi-month tracking.

```typescript
export interface Player {
  id: string;
  name: string;
  photoUrl: string;
  isPaid: boolean;
  paymentDate?: string;
  value: number;
  jerseyNumber: number;
  status: 'active' | 'injured';
  paymentHistory: Record<string, string>; // Stores { "MM-YYYY": "DD/MM/YYYY" }
}

// Interface que espelha as colunas do banco de dados Supabase
export interface DbPlayer {
  id: number;
  name: string;
  photo_url: string;
  is_paid: boolean;
  payment_date: string | null;
  value: number;
  jersey_number: number;
  status: string;
}

export interface DashboardStats {
  totalCollected: number;
  totalPending: number;
  currentDate: string;
  dueDate: string;
}
```

## App.tsx

Refactored `App.tsx` to:
1.  Parse `payment_date` as a JSON history object.
2.  Derive `isPaid` and `paymentDate` for the UI based on the `selectedDate` (Month/Year).
3.  Update the `togglePayment` logic to modify the history object and save it back to Supabase as JSON.
4.  Update stats and lists to reflect the currently selected month.

```tsx
import React, { useState, useEffect, useMemo, ChangeEvent } from 'react';
import { Player, DbPlayer } from './types';
import { getSupabase, saveSupabaseKey, SUPABASE_URL } from './supabaseClient';

const DEFAULT_FEE = 40;

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [players, setPlayers] = useState<Player[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  // Conexão State
  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [apiKeyInput, setApiKeyInput] = useState('');
  const [isConnected, setIsConnected] = useState(false);

  // Edit State
  const [editingDateId, setEditingDateId] = useState<string | null>(null);
  const [editingNameId, setEditingNameId] = useState<string | null>(null);
  const [editingJerseyId, setEditingJerseyId] = useState<string | null>(null);
  const [tempName, setTempName] = useState<string>('');

  // Modal State
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerNumber, setNewPlayerNumber] = useState('');
  const [newPlayerPhoto, setNewPlayerPhoto] = useState<string | null>(null);

  // Theme Toggle Effect
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  // --- HELPER: Date Key for Payment History ---
  const getMonthKey = (date: Date) => {
    const m = (date.getMonth() + 1).toString().padStart(2, '0');
    const y = date.getFullYear();
    return `${m}-${y}`;
  };

  const parsePaymentHistory = (dateStr: string | null): Record<string, string> => {
    if (!dateStr) return {};
    try {
        // Tenta ler como JSON (formato novo)
        return JSON.parse(dateStr);
    } catch (e) {
        // Fallback: Tenta ler como data simples antiga "DD/MM/YYYY" ou "YYYY-MM-DD"
        if (dateStr.includes('/')) {
            const parts = dateStr.split('/');
            if (parts.length === 3) {
                 // Assume formato DD/MM/YYYY
                 const key = `${parts[1]}-${parts[2]}`;
                 return { [key]: dateStr };
            }
        } else if (dateStr.includes('-')) {
             // Assume formato YYYY-MM-DD
             const parts = dateStr.split('-');
             if (parts.length === 3) {
                const key = `${parts[1]}-${parts[0]}`;
                return { [key]: `${parts[2]}/${parts[1]}/${parts[0]}` };
             }
        }
        return {};
    }
  };

  // --- SUPABASE INTEGRATION ---

  // 1. Check connection & Load Data
  useEffect(() => {
    const supabase = getSupabase();

    // Se não tiver instância (o que não deve acontecer com a chave hardcoded), pede a chave
    if (!supabase) {
      setApiKeyModalOpen(true);
      setLoading(false);
      return;
    }

    setIsConnected(true);
    fetchPlayers();

    // 2. Realtime Subscription
    const channel = supabase
      .channel('realtime-players')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'players' }, (payload) => {
        fetchPlayers();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const fetchPlayers = async () => {
    const supabase = getSupabase();
    if (!supabase) return;

    try {
      const { data, error } = await supabase
        .from('players')
        .select('*')
        .order('name', { ascending: true });

      if (error) {
        console.error("Erro Supabase:", error);
        return;
      }

      if (data) {
        const mappedPlayers: Player[] = data.map((p: DbPlayer) => ({
          id: p.id.toString(),
          name: p.name,
          photoUrl: p.photo_url || 'https://via.placeholder.com/150',
          // isPaid e paymentDate serão calculados dinamicamente na view
          isPaid: false, 
          paymentDate: undefined,
          value: p.value,
          jerseyNumber: p.jersey_number,
          status: (p.status === 'injured' ? 'injured' : 'active') as 'active' | 'injured',
          paymentHistory: parsePaymentHistory(p.payment_date)
        }));
        setPlayers(mappedPlayers);
      }
    } catch (error) {
      console.error("Erro ao buscar jogadores:", error);
    } finally {
      setLoading(false);
    }
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  const formattedDate = useMemo(() => {
    const options: Intl.DateTimeFormatOptions = { month: 'long', year: 'numeric' };
    const str = selectedDate.toLocaleDateString('pt-BR', options);
    return str.charAt(0).toUpperCase() + str.slice(1);
  }, [selectedDate]);

  const changeMonth = (increment: number) => {
    const newDate = new Date(selectedDate);
    newDate.setMonth(newDate.getMonth() + increment);
    setSelectedDate(newDate);
  };

  // --- DERIVED PLAYERS FOR CURRENT MONTH ---
  const currentMonthKey = getMonthKey(selectedDate);

  const playersView = useMemo(() => {
    return players.map(player => {
        const paymentDateForMonth = player.paymentHistory[currentMonthKey];
        return {
            ...player,
            isPaid: !!paymentDateForMonth,
            paymentDate: paymentDateForMonth
        };
    });
  }, [players, currentMonthKey]);

  const financialStats = useMemo(() => {
    const activePlayers = playersView.filter(p => p.status === 'active' || p.isPaid);
    const totalCollected = playersView.reduce((acc, player) => acc + (player.isPaid ? player.value : 0), 0);
    const potentialTotal = activePlayers.reduce((acc, player) => acc + player.value, 0);
    const paidCount = playersView.filter(p => p.isPaid).length;
    const totalCount = activePlayers.length;
    const progress = totalCount > 0 ? (paidCount / totalCount) * 100 : 0;

    return { totalCollected, potentialTotal, paidCount, totalCount, progress };
  }, [playersView]);

  const topPayers = useMemo(() => {
    return playersView.filter(p => p.isPaid && p.status === 'active').slice(0, 3);
  }, [playersView]);

  // --- ACTIONS (Database) ---

  const handleSaveKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (apiKeyInput.trim()) {
      saveSupabaseKey(apiKeyInput.trim());
      setApiKeyModalOpen(false);
    }
  };

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;

    const player = players.find(p => p.id === id);
    if (!player) return;

    const newHistory = { ...player.paymentHistory };
    const isCurrentlyPaid = !!newHistory[currentMonthKey];

    if (isCurrentlyPaid) {
        delete newHistory[currentMonthKey];
    } else {
        newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');
    }

    // Update local state immediately for responsiveness
    setPlayers(prev => prev.map(p => 
        p.id === id ? { ...p, paymentHistory: newHistory } : p
    ));

    // Save history as JSON string
    await supabase
      .from('players')
      .update({ 
          payment_date: JSON.stringify(newHistory),
          is_paid: !isCurrentlyPaid // Optional: update boolean for simple DB check, though logic relies on JSON
      })
      .eq('id', id);
  };

  const updatePaymentDate = async (id: string, dateValue: string) => {
    if (!dateValue) return;
    const [year, month, day] = dateValue.split('-');
    const formattedDate = `${day}/${month}/${year}`;

    const player = players.find(p => p.id === id);
    if (!player) return;

    const newHistory = { ...player.paymentHistory, [currentMonthKey]: formattedDate };

    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));

    const supabase = getSupabase();
    if (supabase) {
        await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
    }

    setEditingDateId(null);
  };

  // --- Player Management Actions ---

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
         setNewPlayerPhoto(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdatePlayerPhoto = async (id: string, e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = async () => {
         const base64 = reader.result as string;
         const supabase = getSupabase();
         if(supabase) {
             await supabase.from('players').update({ photo_url: base64 }).eq('id', id);
         }
      };
      reader.readAsDataURL(file);
    }
  };

  const deletePlayer = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Tem certeza que deseja remover este jogador?")) {
      const supabase = getSupabase();
      if(supabase) {
          await supabase.from('players').delete().eq('id', id);
      }
      setPlayers(prev => prev.filter(p => p.id !== id));
    }
  };

  const togglePlayerStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const player = players.find(p => p.id === id);
    if(!player) return;

    const newStatus = player.status === 'active' ? 'injured' : 'active';

    const supabase = getSupabase();
    if(supabase) {
        await supabase.from('players').update({ status: newStatus }).eq('id', id);
    }

    setPlayers(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
  };

  // --- Name Editing ---
  const startEditingName = (player: Player) => {
    if (player.status === 'injured') return;
    setEditingNameId(player.id);
    setTempName(player.name);
  };

  const savePlayerName = async (id: string) => {
    if (tempName.trim()) {
      const supabase = getSupabase();
      if(supabase) {
          await supabase.from('players').update({ name: tempName.trim() }).eq('id', id);
      }
      setPlayers(prev => prev.map(p => p.id === id ? { ...p, name: tempName.trim() } : p));
    }
    setEditingNameId(null);
  };

  // --- Jersey Editing ---
  const saveJerseyNumber = async (id: string, newNumber: string) => {
    const num = parseInt(newNumber);
    if (!isNaN(num)) {
         const supabase = getSupabase();
         if(supabase) {
             await supabase.from('players').update({ jersey_number: num }).eq('id', id);
         }
         setPlayers(prev => prev.map(p => p.id === id ? { ...p, jerseyNumber: num } : p));
    }
    setEditingJerseyId(null);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto) return;

    const newPlayerDb = {
      name: newPlayerName,
      photo_url: newPlayerPhoto,
      is_paid: false, // Default initial
      value: DEFAULT_FEE,
      jersey_number: parseInt(newPlayerNumber) || 0,
      status: 'active',
      payment_date: JSON.stringify({}) // Initialize empty history
    };

    const supabase = getSupabase();
    if (supabase) {
        await supabase.from('players').insert([newPlayerDb]);
    }

    setNewPlayerName('');
    setNewPlayerNumber('');
    setNewPlayerPhoto(null);
    setIsAddModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark text-gray-900 dark:text-gray-100 font-display p-6 lg:p-10 transition-colors duration-300 relative">

      {/* Light Mode Gradient Background */}
      {theme === 'light' && (
        <div className="fixed inset-0 overflow-hidden pointer-events-none -z-10">
           <div className="absolute -top-[10%] -left-[10%] w-[50%] h-[50%] bg-primary/10 rounded-full blur-[120px]"></div>
           <div className="absolute top-[20%] -right-[10%] w-[40%] h-[40%] bg-primary/10 rounded-full blur-[100px]"></div>
           <div className="absolute -bottom-[10%] left-[20%] w-[60%] h-[40%] bg-primary/5 rounded-full blur-[100px]"></div>
        </div>
      )}

      <div className="max-w-7xl mx-auto space-y-10">

        {/* Header Minimalista */}
        <header className="flex justify-between items-center pb-6 border-b border-gray-200 dark:border-gray-800">
          <div className="flex items-center gap-3">
             <img src="https://i.imgur.com/GSj0ZPy.png" alt="Pesadão F.C Logo" className="w-16 h-16 object-contain" />
             <div>
                <h1 className="text-2xl font-bold tracking-tight">Pesadão F.C<span className="text-primary">.</span></h1>
                <div className="flex items-center gap-2">
                    <p className="text-sm text-muted-light dark:text-muted-dark font-medium">Mensalidade / @pesadaofut</p>
                    <span className={`flex h-2 w-2 rounded-full ${isConnected ? 'bg-green-500' : 'bg-red-500 animate-pulse'}`} title={isConnected ? "Conectado ao Banco" : "Desconectado"}></span>
                </div>
             </div>
          </div>

          <div className="flex items-center gap-2">
            <button 
                onClick={toggleTheme}
                className="w-10 h-10 rounded-full bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-700 flex items-center justify-center text-muted-light dark:text-muted-dark hover:text-primary transition-colors shadow-sm"
            >
                <span className="material-icons-outlined">
                {theme === 'dark' ? 'light_mode' : 'dark_mode'}
                </span>
            </button>
          </div>
        </header>

        {/* Top Section: Stats & Top 3 */}
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

          {/* Caixa Mensal (Hero Card) */}
          <div className="xl:col-span-1 bg-surface-light dark:bg-surface-dark rounded-2xl p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden group flex flex-col justify-between h-full min-h-[220px]">
            <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

            <div className="relative z-10">
              <h2 className="text-muted-light dark:text-muted-dark font-medium mb-1">Total em Caixa ({formattedDate})</h2>
              <div className="flex items-baseline gap-2 mb-6">
                <span className="text-5xl font-bold tracking-tighter text-gray-900 dark:text-white">
                  R$ {financialStats.totalCollected}
                </span>
                <span className="text-lg text-muted-light dark:text-muted-dark font-medium">
                  / {financialStats.potentialTotal}
                </span>
              </div>
            </div>

            {/* Progress Bar */}
            <div className="relative z-10 mt-auto">
              <div className="flex justify-between text-sm font-semibold mb-3">
                <span className="text-primary">{financialStats.paidCount} Pagos</span>
                <span className="text-muted-light dark:text-muted-dark">{financialStats.totalCount - financialStats.paidCount} Pendentes</span>
              </div>
              <div className="w-full bg-gray-200 dark:bg-gray-800 rounded-full h-4 overflow-hidden">
                <div 
                  className="bg-primary h-4 rounded-full transition-all duration-700 ease-out" 
                  style={{ width: `${financialStats.progress}%` }}
                ></div>
              </div>
            </div>
          </div>

           {/* Top 3 Pagadores (Podium Section) */}
           <div className="xl:col-span-2 bg-surface-light dark:bg-surface-dark rounded-2xl p-8 border border-gray-200 dark:border-gray-800 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-2 mb-6">
                <span className="material-icons-outlined text-yellow-500">emoji_events</span>
                <h3 className="font-bold text-lg">Top 3 Pagadores ({formattedDate})</h3>
              </div>

              <div className="flex items-end justify-around h-40 pb-2">
                {/* 2nd Place */}
                {topPayers[1] ? (
                   <div className="flex flex-col items-center gap-2 group cursor-pointer">
                      <div className="relative">
                        <img src={topPayers[1].photoUrl} alt={topPayers[1].name} className="w-16 h-16 rounded-full border-4 border-gray-300 dark:border-gray-600 object-cover" />
                        <div className="absolute -bottom-3 left-1/2 -translate-x-1/2 bg-gray-300 dark:bg-gray-600 text-surface-dark text-xs font-bold w-6 h-6 rounded-full flex items-center justify-center">2</div>
                      </div>
                      <div className="text-center mt-2">
                        <p className="font-bold text-sm truncate max-w-[100px]">{topPayers[1].name}</p>
                        <p className="text-[10px] text-muted-light dark:text-muted-dark">#{topPayers[1].jerseyNumber}</p>
                      </div>
                   </div>
                ) : <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-gray-800/50 flex items-center justify-center text-xs opacity-50">2º Lugar</div>}

                {/* 1st Place */}
                {topPayers[0] ? (
                   <div className="flex flex-col items-center gap-2 mb-4 group cursor-pointer">
                      <div className="relative">
                        <span className="absolute -top-6 left-1/2 -translate-x-1/2 material-icons-outlined text-yellow-400 animate-bounce">crown</span>
                        <img src={topPayers[0].photoUrl} alt={topPayers[0].name} className="w-24 h-24 rounded-full border-4 border-yellow-400 object-cover shadow-[0_0_20px_rgba(250,204,21,0.3)]" />
                        <div className="absolute -bottom-3 left-1/2 -translate-x-1/2 bg-yellow-400 text-surface-dark text-sm font-bold w-8 h-8 rounded-full flex items-center justify-center border-2 border-surface-light dark:border-surface-dark">1</div>
                      </div>
                      <div className="text-center mt-2">
                        <p className="font-bold text-base truncate max-w-[120px]">{topPayers[0].name}</p>
                        <p className="text-xs text-primary font-bold">R$ {topPayers[0].value}</p>
                      </div>
                   </div>
                ) : <div className="w-24 h-24 rounded-full bg-gray-100 dark:bg-gray-800/50 flex items-center justify-center text-sm opacity-50 border-2 border-dashed border-gray-300 dark:border-gray-700">1º Lugar</div>}

                {/* 3rd Place */}
                {topPayers[2] ? (
                   <div className="flex flex-col items-center gap-2 group cursor-pointer">
                      <div className="relative">
                        <img src={topPayers[2].photoUrl} alt={topPayers[2].name} className="w-16 h-16 rounded-full border-4 border-orange-700/60 dark:border-orange-800 object-cover" />
                        <div className="absolute -bottom-3 left-1/2 -translate-x-1/2 bg-orange-700/60 dark:bg-orange-800 text-white text-xs font-bold w-6 h-6 rounded-full flex items-center justify-center">3</div>
                      </div>
                      <div className="text-center mt-2">
                        <p className="font-bold text-sm truncate max-w-[100px]">{topPayers[2].name}</p>
                        <p className="text-[10px] text-muted-light dark:text-muted-dark">#{topPayers[2].jerseyNumber}</p>
                      </div>
                   </div>
                ) : <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-gray-800/50 flex items-center justify-center text-xs opacity-50">3º Lugar</div>}
              </div>
           </div>

        </div>

        {/* Squad Section */}
        <div className="space-y-6">

          {/* Section Header with Date Selector and Action Button */}
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
             <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                <h3 className="text-xl font-bold flex items-center gap-2">
                  Elenco
                  <span className="bg-gray-200 dark:bg-gray-800 text-xs px-2 py-1 rounded-md text-muted-light dark:text-muted-dark">
                      {loading ? '...' : playersView.length}
                  </span>
                </h3>

                {/* Date Selector Moved Here */}
                <div className="flex items-center gap-2 bg-surface-light dark:bg-surface-dark px-2 py-1.5 rounded-full border border-gray-200 dark:border-gray-700 shadow-sm self-start sm:self-auto">
                  <button 
                    onClick={() => changeMonth(-1)}
                    className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-muted-light dark:text-muted-dark transition-colors"
                  >
                    <span className="material-icons-outlined text-sm">arrow_back_ios</span>
                  </button>

                  <div className="flex items-center gap-2 px-2 min-w-[140px] justify-center">
                    <span className="material-icons-outlined text-primary">calendar_today</span>
                    <span className="font-bold text-sm capitalize">{formattedDate}</span>
                  </div>

                  <button 
                    onClick={() => changeMonth(1)}
                    className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-muted-light dark:text-muted-dark transition-colors"
                  >
                    <span className="material-icons-outlined text-sm">arrow_forward_ios</span>
                  </button>
                </div>
             </div>

             <button 
               onClick={() => setIsAddModalOpen(true)}
               disabled={!isConnected}
               className="flex items-center justify-center gap-2 bg-primary hover:opacity-90 text-surface-light dark:text-surface-dark font-bold px-4 py-2 rounded-xl transition-all shadow-lg shadow-primary/20 text-sm disabled:opacity-50 disabled:cursor-not-allowed"
             >
               <span className="material-icons-outlined text-lg">add</span>
               Novo Jogador
             </button>
          </div>

          {loading ? (
              <div className="flex justify-center py-20">
                  <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
              </div>
          ) : (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-6">
            {playersView.map((player) => (
              <div 
                key={player.id} 
                className={`
                  relative bg-surface-light dark:bg-surface-dark rounded-2xl p-6 flex flex-col items-center text-center border transition-all duration-300 group
                  ${player.status === 'injured' 
                    ? 'border-red-500/20 opacity-90 grayscale-[0.5]' 
                    : player.isPaid 
                        ? 'border-primary/30 shadow-[0_0_15px_-5px_rgba(var(--color-primary-rgb),0.15)]' 
                        : 'border-gray-200 dark:border-gray-800 hover:border-gray-300 dark:hover:border-gray-600'
                  }
                `}
              >
                {/* Subtle Action Buttons (Top Right) */}
                <div className="absolute top-3 right-3 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity z-30">
                    <button 
                      onClick={(e) => togglePlayerStatus(player.id, e)}
                      className="w-6 h-6 flex items-center justify-center rounded-full bg-gray-100 dark:bg-gray-800 hover:bg-yellow-100 dark:hover:bg-yellow-900/30 text-gray-500 hover:text-yellow-600 transition-colors"
                      title={player.status === 'active' ? "Reportar Lesão" : "Retornar ao Elenco"}
                    >
                      <span className="material-icons-outlined text-[14px]">medical_services</span>
                    </button>
                    <button 
                      onClick={(e) => deletePlayer(player.id, e)}
