        };
    });
  }, [players, currentMonthKey]);

  const financialStats = useMemo(() => {
    const activePlayers = playersView.filter(p => p.status === 'active' || p.isPaid);
    const totalCollected = playersView.reduce((acc, player) => acc + (player.isPaid ? player.value : 0), 0);
    const potentialTotal = activePlayers.reduce((acc, player) => acc + player.value, 0);
    const paidCount = playersView.filter(p => p.isPaid).length;
    const totalCount = activePlayers.length;
    const progress = totalCount > 0 ? (paidCount / totalCount) * 100 : 0;
    return { totalCollected, potentialTotal, paidCount, totalCount, progress };
  }, [playersView]);

  const topPayers = useMemo(() => {
    return playersView.filter(p => p.isPaid && p.status === 'active').slice(0, 3);
  }, [playersView]);

  const matchStats = useMemo(() => {
    const finished = matches.filter(m => m.isFinished);
    const wins = finished.filter(m => m.result === 'win').length;
    const draws = finished.filter(m => m.result === 'draw').length;
    const losses = finished.filter(m => m.result === 'loss').length;
    const total = finished.length;
    const winRate = total > 0 ? Math.round((wins / total) * 100) : 0;
    return { wins, draws, losses, total, winRate };
  }, [matches]);

  const topScorers = useMemo(() => [...players].sort((a, b) => b.goals - a.goals).slice(0, 5), [players]);
  const topAssists = useMemo(() => [...players].sort((a, b) => b.assists - a.assists).slice(0, 5), [players]);

  // --- ACTIONS ---

  const handleSaveKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (apiKeyInput.trim()) {
      saveSupabaseKey(apiKeyInput.trim());
      setApiKeyModalOpen(false);
    }
  };

  const togglePayment = async (id: string) => {
    const supabase = getSupabase();
    if (!supabase) return;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory };
    const isCurrentlyPaid = !!newHistory[currentMonthKey];

    if (isCurrentlyPaid) delete newHistory[currentMonthKey];
    else newHistory[currentMonthKey] = new Date().toLocaleDateString('pt-BR');

    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    await supabase.from('players').update({ payment_date: JSON.stringify(newHistory), is_paid: !isCurrentlyPaid }).eq('id', id);
  };

  const updatePaymentDate = async (id: string, dateValue: string) => {
    if (!dateValue) return;
    const [year, month, day] = dateValue.split('-');
    const formattedDate = `${day}/${month}/${year}`;
    const player = players.find(p => p.id === id);
    if (!player) return;
    const newHistory = { ...player.paymentHistory, [currentMonthKey]: formattedDate };
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, paymentHistory: newHistory } : p));
    setEditingDateId(null);
    const supabase = getSupabase();
    if (supabase) await supabase.from('players').update({ payment_date: JSON.stringify(newHistory) }).eq('id', id);
  };

  const handlePhotoUpload = (e: ChangeEvent<HTMLInputElement>, setter: (val: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => setter(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleUpdatePlayerPhoto = async (id: string, e: ChangeEvent<HTMLInputElement>) => {
