    setEditingJerseyId(null);
  };

  const handleAddPlayer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlayerName.trim() || !newPlayerPhoto) return;

    const newPlayerDb = {
      name: newPlayerName,
      photo_url: newPlayerPhoto,
      is_paid: false,
      value: DEFAULT_FEE,
      jersey_number: parseInt(newPlayerNumber) || 0,
      status: 'active',
      payment_date: JSON.stringify({}),
      position: 'MEI',
      goals: 0,
      assists: 0,
      matches_played: 0,
      overall: 70
    };

    const supabase = getSupabase();
    if (supabase) {
        const { error } = await supabase.from('players').insert([newPlayerDb]);
        if (error) {
            alert(`Erro ao adicionar jogador: ${error.message}. Verifique se as colunas (goals, assists, overall) foram criadas no Supabase.`);
            return; // Don't clear form if failed
        }
        fetchData(); // Refresh immediately
