  const openEditStats = (player: Player) => {
      setTempStats({
          goals: player.goals,
          assists: player.assists,
          matchesPlayed: player.matchesPlayed,
          overall: player.overall,
          position: player.position
      });
      setEditingStatsId(player.id);
  };

  const savePlayerStats = async () => {
      if(!editingStatsId) return;
      const supabase = getSupabase();
      if(supabase) {
          const { error } = await supabase.from('players').update({
              goals: tempStats.goals,
              assists: tempStats.assists,
              matches_played: tempStats.matchesPlayed,
              overall: tempStats.overall,
              position: tempStats.position
          }).eq('id', editingStatsId);

          if (error) {
              alert("Erro ao salvar estatísticas: " + error.message);
          } else {
             setPlayers(prev => prev.map(p => p.id === editingStatsId ? {
                ...p, 
                goals: tempStats.goals, 
                assists: tempStats.assists, 
                matchesPlayed: tempStats.matchesPlayed,
                overall: tempStats.overall,
                position: tempStats.position
             } : p));
          }
      }
      setEditingStatsId(null);
  };

  const handleAddMatch = async (e: React.FormEvent) => {
    e.preventDefault();
    const supabase = getSupabase();
    if(supabase) {
        const { error } = await supabase.from('matches').insert([{
            opponent: newMatchOpponent,
            date: newMatchDate,
            time: newMatchTime,
            location_img: newMatchLocationImg,
            result: 'pending',
            is_finished: false
        }]);

        if (error) {
            alert(`Erro ao criar partida: ${error.message}. Verifique se a tabela 'matches' existe no Supabase.`);
            return;
        }
        fetchData(); // Refresh
    }
    setNewMatchOpponent('');
    setNewMatchDate('');
    setNewMatchTime('');
    setNewMatchLocationImg(null);
    setIsAddModalOpen(false);
  };

  const updateMatchResult = async (match: Match, result: string) => {
      const supabase = getSupabase();
      if(!supabase) return;

      let updates: any = { result, is_finished: true };

      if (result === 'win') { updates.home_score = 3; updates.away_score = 1; }
      else if (result === 'loss') { updates.home_score = 1; updates.away_score = 3; }
      else if (result === 'draw') { updates.home_score = 2; updates.away_score = 2; }
      else { updates.is_finished = false; updates.home_score = 0; updates.away_score = 0; }

      await supabase.from('matches').update(updates).eq('id', match.id);

      setMatches(prev => prev.map(m => m.id === match.id ? { ...m, ...updates, result: result as any } : m));
