  const updateMatchStat = (playerId: string, type: 'goals' | 'assists', delta: number) => {
      setMatchPlayerStats(prev => ({
          ...prev,
          [playerId]: {
              ...prev[playerId],
              [type]: Math.max(0, (prev[playerId]?.[type] || 0) + delta)
          }
      }));
  };

  const confirmMatchResult = async () => {
      if (!selectedMatch) return;
      const supabase = getSupabase();
      if (!supabase) return;

      setIsSubmitting(true);

      // 1. Determine Result
      let result = 'draw';
      if (manualHomeScore > manualAwayScore) result = 'win';
      if (manualHomeScore < manualAwayScore) result = 'loss';

      // 2. Update Match
      await supabase.from('matches').update({
          home_score: manualHomeScore,
          away_score: manualAwayScore,
          result: result,
          is_finished: true
      }).eq('id', selectedMatch.id);

      // 3. Update Player Stats (Only if this is the first time finishing OR user explicitly wants to add stats)
      // Logic: Iterate through local stats map and update DB for players with > 0 stats
      // Note: This adds to existing stats. It does not replace. 
      const updates = [];

      // Only process stats if match wasn't finished before (to avoid double counting on edit)
      // OR allow it but warn user. For simplicity in this UX, we process if any stat > 0.

      if (!selectedMatch.isFinished) {
          for (const playerId in matchPlayerStats) {
             const stats = matchPlayerStats[playerId];
             if (stats.goals > 0 || stats.assists > 0) {
                 const player = players.find(p => p.id === playerId);
                 if (player) {
                     updates.push(
                         supabase.from('players').update({
                             goals: player.goals + stats.goals,
                             assists: player.assists + stats.assists,
                             matches_played: player.matchesPlayed + 1 // Increment match played
                         }).eq('id', playerId)
                     );
                 }
             } else {
                 // Even if no goals/assists, increment match played for all active?
                 // Let's assume user marks participation by stats for now to keep it simple, 
                 // or we can add a 'participated' toggle later.
                 const player = players.find(p => p.id === playerId);
                 if (player) {
                      updates.push(
                         supabase.from('players').update({
                             matches_played: player.matchesPlayed + 1
                         }).eq('id', playerId)
                     );
                 }
             }
          }
      }

      await Promise.all(updates);

      await fetchData();
      setIsMatchResultModalOpen(false);
      setIsSubmitting(false);
