    const displayMatches = matchViewMode === 'upcoming' ? upcomingMatches : finishedMatches;

    return (
    <div className="space-y-8 animation-fade-in pb-20">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
