                    <h3 className="text-lg font-bold">Agenda de Jogos</h3>
                    <div className="flex bg-gray-200 dark:bg-surface-dark p-1 rounded-lg">
                        <button onClick={() => setMatchViewMode('upcoming')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${matchViewMode === 'upcoming' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Próximos</button>
                        <button onClick={() => setMatchViewMode('history')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${matchViewMode === 'history' ? 'bg-white dark:bg-gray-700 shadow text-primary' : 'text-muted-light'}`}>Histórico</button>
                    </div>
                </div>

                <button onClick={() => setIsAddModalOpen(true)} className="hidden md:flex bg-primary hover:opacity-90 text-white px-4 py-2 rounded-xl font-bold text-sm shadow-lg shadow-primary/20 items-center gap-2">
                    <span className="material-icons-outlined text-lg">add</span> Nova Partida
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {displayMatches.map(m => (
                    <div 
                        key={m.id} 
                        className={`relative rounded-2xl overflow-hidden flex flex-col shadow-sm animation-fade-in group transition-all duration-300
                            ${matchViewMode === 'upcoming' 
                                ? 'bg-gradient-to-br from-primary to-orange-500 dark:from-primary dark:to-orange-500 text-white shadow-lg' 
                                : 'bg-surface-light dark:bg-surface-dark border border-gray-200 dark:border-gray-800 grayscale opacity-80 hover:grayscale-0 hover:opacity-100'
                            }`}
                    >
                        <div className="absolute top-3 right-3 z-50">
                            <button onClick={(e) => deleteMatch(m.id, e)} className={`p-2 rounded-full transition-colors cursor-pointer ${matchViewMode === 'upcoming' ? 'text-white/80 hover:bg-white/20 hover:text-white' : 'text-gray-400 hover:text-red-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>
                                <span className="material-icons-outlined text-lg">delete_outline</span>
                            </button>
                        </div>

