                    {topAssists.map((p, i) => (
                        <div key={p.id} className="flex items-center justify-between p-2 hover:bg-gray-50 dark:hover:bg-gray-800/50 rounded-lg transition-colors">
                            <div className="flex items-center gap-3">
                                <span className="font-bold text-muted-light w-4">{i+1}</span>
                                <img src={p.photoUrl} className="w-8 h-8 rounded-full object-cover" />
                                <span className="font-semibold text-sm">{p.name}</span>
                            </div>
                            <span className="font-bold bg-blue-500/10 text-blue-500 px-2 py-0.5 rounded text-sm">{p.assists}</span>
                        </div>
                    ))}
                    {topAssists.length === 0 && <p className="text-muted-light text-sm">Sem dados</p>}
                </div>
            </div>
        </div>

        <h3 className="text-xl font-bold mt-8">Jogadores</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
             {players.map(p => (
                 <div 
                    key={p.id} 
                    onClick={() => openPlayerProfile(p)} 
                    className="cursor-pointer group relative bg-surface-light dark:bg-surface-dark rounded-[2rem] border border-gray-200 dark:border-gray-800 p-5 transition-all duration-300 hover:shadow-2xl hover:-translate-y-1 hover:border-primary/40 overflow-hidden"
                 >
                      {/* Hover Decoration Background */}
                      <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full blur-3xl -mr-16 -mt-16 transition-opacity opacity-0 group-hover:opacity-100 pointer-events-none"></div>

                      {/* Header: Number & Position */}
                      <div className="flex justify-between items-start mb-2 relative z-10">
                          <span className="font-display font-black text-3xl text-gray-100 dark:text-gray-800 group-hover:text-primary/10 transition-colors">
                              {p.jerseyNumber}
                          </span>
                          <span className="px-3 py-1 rounded-full bg-gray-100 dark:bg-gray-800/80 text-[10px] font-bold uppercase tracking-wider text-muted-light group-hover:bg-primary group-hover:text-white transition-colors shadow-sm backdrop-blur-sm">
                              {p.position}
                          </span>
                      </div>

                      {/* Center: Image & Name */}
                      <div className="flex flex-col items-center mb-6 relative z-10">
                          <div className="relative mb-3">
                              {/* Glow effect */}
                              <div className="absolute inset-0 bg-primary/20 rounded-full blur-md opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                              <img 
                                src={p.photoUrl} 
                                className="relative w-28 h-28 rounded-full object-cover border-4 border-surface-light dark:border-surface-dark shadow-lg group-hover:border-primary/50 transition-colors" 
                              />
                              {/* Status indicator */}
                              <div className={`absolute bottom-1 right-1 w-5 h-5 rounded-full border-4 border-surface-light dark:border-surface-dark ${p.status === 'active' ? 'bg-green-500' : 'bg-red-500'} shadow-sm`}></div>
                          </div>
                          <h4 className="font-bold text-xl text-center truncate w-full px-2 text-gray-900 dark:text-gray-100">{p.name}</h4>
